export function typeLabelRuWithOriginal(typeRaw) {
  const source = toText(typeRaw);
  const key = source.replace(/^bpmn:/i, "").toLowerCase();
  const labelRu = toText(BPMN_TYPE_LABELS_RU[key]);
  if (labelRu) return `${labelRu}(${key})`;
  return typeLabel(source);
}

export function durationClass(min) {
  if (min > 30) return "hi";
  if (min >= 10) return "mid";
  return "low";
}

export function durationLabel(min) {
  if (min > 30) return ">30";
  if (min >= 10) return "10-30";
  return "<10";
}

export function round1(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return 0;
  return Math.round(n * 10) / 10;
}

export function percent(part, total) {
  const p = Number(part);
  const t = Number(total);
  if (!Number.isFinite(p) || !Number.isFinite(t) || t <= 0) return 0;
  return round1((p / t) * 100);
}

export function formatPercent(v) {
  const n = round1(v);
  return Number.isInteger(n) ? `${n}%` : `${n.toFixed(1)}%`;
}

export function laneColor(key, idx) {
  const laneIdx = Number(idx);
  if (Number.isFinite(laneIdx) && laneIdx > 0) {
    // Golden-angle palette: stable and non-repeating for practical lane counts.
    const hue = (laneIdx * 137.508) % 360;
    const sat = 72 + (laneIdx % 4) * 5;
    const light = 64 + (laneIdx % 3) * 4;
    return `hsl(${hue.toFixed(3)} ${sat}% ${light}%)`;
  }
  let h = 19;
  const src = String(key || "lane").toLowerCase();
  for (let i = 0; i < src.length; i += 1) {
    h = (h * 31 + src.charCodeAt(i)) % 360;
  }
  const sat = 74 + (h % 4) * 4;
  const light = 62 + (h % 3) * 5;
  return `hsl(${h} ${sat}% ${light}%)`;
}

export function laneLabel(name, idx) {
  const laneName = toText(name) || "unassigned";
  const laneIdx = Number(idx);
  if (Number.isFinite(laneIdx) && laneIdx > 0) return `L${laneIdx}: ${laneName}`;
  return laneName;
}

export function laneLabelShort(name, idx) {
  const laneIdx = Number(idx);
  if (Number.isFinite(laneIdx) && laneIdx > 0) return `L${laneIdx}`;
  return toText(name) || "L?";
}

export function laneCellDisplay(stepLaneIdx, stepLaneName, transitionLaneLinks) {
  const selfShort = laneLabelShort(stepLaneName, stepLaneIdx);
  const selfFull = laneLabel(stepLaneName, stepLaneIdx);
  if (!transitionLaneLinks || !transitionLaneLinks.length) {
    return { text: selfShort, tooltip: selfFull };
  }
  const outgoing = transitionLaneLinks.find((t) => t.direction === "out");
  const incoming = transitionLaneLinks.find((t) => t.direction === "in");
  const transition = outgoing || incoming;
  if (!transition) {
    return { text: selfShort, tooltip: selfFull };
  }
  const otherShort = laneLabelShort(transition.laneName, transition.laneIdx);
  const otherFull = laneLabel(transition.laneName, transition.laneIdx);
  if (transition.direction === "out") {
    return { text: `${selfShort} → ${otherShort}`, tooltip: `${selfFull} → ${otherFull}` };
  }
  return { text: `${otherShort} → ${selfShort}`, tooltip: `${otherFull} → ${selfFull}` };
}

