function MetricCard({ label, value, hint = "" }) {
  return (
    <article className="productActionsRegistryMetricCard">
      <div className="productActionsRegistryMetricLabel">{label}</div>
      <div className="productActionsRegistryMetricValue">{value}</div>
      {hint ? <div className="productActionsRegistryMetricHint">{hint}</div> : null}
    </article>
  );
}

export default function ProductActionsRegistryMetrics({
  visibleSessionTotal = 0,
  summary = {},
  filteredSummary = {},
}) {
  function fmt(n) {
    const v = Number(n);
    return Number.isFinite(v) ? v : "—";
  }

  return (
    <section className="productActionsRegistryMetrics" aria-label="Сводка реестра">
      <MetricCard label="Сессий" value={fmt(visibleSessionTotal)} />
      <MetricCard label="Строк" value={fmt(summary.rows)} />
      <MetricCard label="Полных" value={fmt(summary.complete)} />
      <MetricCard label="Неполных" value={fmt(summary.incomplete)} />
      <MetricCard
        label="После фильтров"
        value={fmt(filteredSummary.rows)}
        hint={`полных: ${fmt(filteredSummary.complete)} · неполных: ${fmt(filteredSummary.incomplete)}`}
      />
    </section>
  );
}
